"""
CalibrationConfig — load/save calibration thresholds from JSON.
Falls back to defaults when config file is absent.
"""

import json
from pathlib import Path
from typing import Any, Optional

ROOT = Path(__file__).resolve().parents[4]
DEFAULT_CONFIG_PATH = Path(__file__).resolve().parent / "calibration-config.json"

DEFAULT_CONFIG: dict = {
    "satiation": {
        "coverage_threshold": 0.90,
        "confidence_threshold": 0.80,
        "no_new_facts_cycles": 3,
        "diminishing_returns_ratio": 0.2,
        "max_calls_per_cycle": 50,
        "micro_mode_max_calls": 10,
        "session_start_cooldown_hours": 6,
        "gap_queue_max_per_domain": 50,
        "gap_expiry_days": 30,
        "dedup_similarity_threshold": 0.85,
        "confidence_floor": 0.30,
        "staleness_days": 180,
    },
    "dimensions": [
        "failure_rates",
        "unit_economics",
        "competitive_landscape",
        "moat_patterns",
        "founder_paths",
        "timing_windows",
        "regulatory_risks",
        "compounding_mechanisms",
    ],
    "domains_active": [],
}


class CalibrationConfig:
    def __init__(self, config_path: Optional[Path] = None):
        self._path = Path(config_path) if config_path else DEFAULT_CONFIG_PATH
        self._config = self._load()

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def get(self, section: str, key: str) -> Any:
        """Return config[section][key]. Raises KeyError if missing."""
        return self._config[section][key]

    def update(self, section: str, key: str, value: Any) -> None:
        """Update a single key and persist to JSON."""
        if section not in self._config:
            self._config[section] = {}
        self._config[section][key] = value
        self._save()

    def to_dict(self) -> dict:
        """Return full config as a plain dict (deep copy)."""
        return json.loads(json.dumps(self._config))

    # ------------------------------------------------------------------
    # Internal helpers
    # ------------------------------------------------------------------

    def _load(self) -> dict:
        if self._path.exists():
            try:
                data = json.loads(self._path.read_text(encoding="utf-8"))
                # Merge with defaults so new keys are always present
                merged = json.loads(json.dumps(DEFAULT_CONFIG))
                for section, values in data.items():
                    if isinstance(values, dict) and isinstance(merged.get(section), dict):
                        merged[section].update(values)
                    else:
                        merged[section] = values
                return merged
            except (json.JSONDecodeError, OSError):
                pass
        return json.loads(json.dumps(DEFAULT_CONFIG))

    def _save(self) -> None:
        try:
            self._path.parent.mkdir(parents=True, exist_ok=True)
            self._path.write_text(
                json.dumps(self._config, indent=2, ensure_ascii=False),
                encoding="utf-8",
            )
        except OSError:
            pass  # read-only fs or permission issue — config is still valid in-memory

"""
HungerDashboard — CLI dashboard that reads hunger state from SQLite
and formats ASCII tables for terminal output.
"""

import sqlite3
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional

ROOT = Path(__file__).resolve().parents[4]
VECTORS_DB = ROOT / ".claude" / "data" / "knowledge-distillation" / "decision-vectors.db"

_SEP = "-" * 80


def _fmt_pct(v: Optional[float]) -> str:
    if v is None:
        return "  n/a"
    return f"{v * 100:5.1f}%"


def _fmt_date(iso: Optional[str]) -> str:
    if not iso:
        return "never"
    return iso[:10]


def _table_row(*cols: str, widths: list[int]) -> str:
    parts = [str(c).ljust(w) for c, w in zip(cols, widths)]
    return "  ".join(parts)


class HungerDashboard:
    def __init__(self, db_path: Optional[Path] = None):
        self.db_path = db_path or VECTORS_DB

    # ------------------------------------------------------------------
    # Public methods — all return formatted strings
    # ------------------------------------------------------------------

    def summary(self) -> str:
        """One line per domain: domain, coverage%, confidence%, last_fed, query_count."""
        rows = self._query_coverage()
        if not rows:
            return "No domain coverage data. Run a hunger cycle first."

        widths = [22, 10, 12, 12, 12]
        header = _table_row("DOMAIN", "COVERAGE%", "CONFIDENCE%", "LAST_FED", "QUERIES",
                            widths=widths)
        lines = [
            "=== Knowledge Hunger Summary ===",
            _SEP,
            header,
            _SEP,
        ]
        for r in rows:
            filled = r.get("dimensions_filled") or 0
            total = max(1, r.get("dimensions_total") or 8)
            cov = filled / total
            conf = r.get("avg_confidence") or 0.0
            lines.append(_table_row(
                r["domain"],
                _fmt_pct(cov),
                _fmt_pct(conf),
                _fmt_date(r.get("last_fed")),
                str(r.get("query_count") or 0),
                widths=widths,
            ))
        lines.append(_SEP)
        return "\n".join(lines)

    def detail(self, domain: str) -> str:
        """Per-dimension breakdown for a domain: fact count, avg confidence, staleness."""
        rows = self._query_vectors_by_domain(domain)
        cov = self._query_coverage_for(domain)

        if cov is None and not rows:
            return f"No data found for domain '{domain}'."

        dim_stats: dict[str, dict] = {}
        for r in rows:
            dim = r.get("dimension") or "unknown"
            s = dim_stats.setdefault(dim, {"count": 0, "conf_sum": 0.0, "dates": []})
            s["count"] += 1
            s["conf_sum"] += r.get("confidence") or 0.0
            d = r.get("created_at") or ""
            if d:
                s["dates"].append(d[:10])

        widths = [26, 8, 12, 12]
        header = _table_row("DIMENSION", "FACTS", "AVG_CONF", "NEWEST_DATE", widths=widths)
        lines = [
            f"=== Detail: {domain} ===",
            _SEP,
            header,
            _SEP,
        ]

        for dim, s in sorted(dim_stats.items()):
            avg_conf = s["conf_sum"] / s["count"] if s["count"] else 0.0
            newest = max(s["dates"]) if s["dates"] else "n/a"
            lines.append(_table_row(
                dim, str(s["count"]), _fmt_pct(avg_conf), newest, widths=widths
            ))

        if not dim_stats:
            lines.append("  (no facts stored yet)")

        lines.append(_SEP)
        if cov:
            filled = cov.get("dimensions_filled") or 0
            total = max(1, cov.get("dimensions_total") or 8)
            lines.append(f"  Overall: {filled}/{total} dims filled, "
                         f"avg_conf={_fmt_pct(cov.get('avg_confidence'))}, "
                         f"queries={cov.get('query_count') or 0}")
        return "\n".join(lines)

    def history(self, n: int = 10) -> str:
        """Last n hunger cycles: date, domain, facts_added, coverage_delta."""
        rows = self._query_hunger_log(n)
        if not rows:
            return "No hunger cycles recorded yet."

        widths = [22, 18, 12, 14, 14]
        header = _table_row("DATE", "DOMAIN", "FACTS_ADDED", "COV_BEFORE", "COV_AFTER",
                            widths=widths)
        lines = [
            f"=== Hunger History (last {n}) ===",
            _SEP,
            header,
            _SEP,
        ]
        for r in rows:
            lines.append(_table_row(
                _fmt_date(r.get("cycle_date")),
                r.get("domain") or "",
                str(r.get("facts_added") or 0),
                _fmt_pct(r.get("coverage_before")),
                _fmt_pct(r.get("coverage_after")),
                widths=widths,
            ))
        lines.append(_SEP)
        return "\n".join(lines)

    def queue(self, limit: int = 20) -> str:
        """Pending gaps sorted by priority."""
        rows = self._query_queue(limit)
        if not rows:
            return "No pending gaps in queue."

        widths = [18, 18, 32, 8]
        header = _table_row("DOMAIN", "DIMENSION", "GAP", "PRIORITY", widths=widths)
        lines = [
            f"=== Hunger Queue (top {limit}) ===",
            _SEP,
            header,
            _SEP,
        ]
        for r in rows:
            gap = (r.get("gap_description") or "")[:30]
            lines.append(_table_row(
                r.get("domain") or "",
                r.get("dimension") or "",
                gap,
                f"{r.get('priority') or 0.5:.2f}",
                widths=widths,
            ))
        lines.append(_SEP)
        return "\n".join(lines)

    # ------------------------------------------------------------------
    # DB helpers
    # ------------------------------------------------------------------

    def _connect(self):
        return sqlite3.connect(str(self.db_path))

    def _query_coverage(self) -> list[dict]:
        if not self.db_path.exists():
            return []
        try:
            with self._connect() as conn:
                conn.row_factory = sqlite3.Row
                rows = conn.execute(
                    "SELECT * FROM domain_coverage ORDER BY query_count DESC"
                ).fetchall()
                return [dict(r) for r in rows]
        except sqlite3.OperationalError:
            return []

    def _query_coverage_for(self, domain: str) -> Optional[dict]:
        if not self.db_path.exists():
            return None
        try:
            with self._connect() as conn:
                conn.row_factory = sqlite3.Row
                row = conn.execute(
                    "SELECT * FROM domain_coverage WHERE domain=?", (domain,)
                ).fetchone()
                return dict(row) if row else None
        except sqlite3.OperationalError:
            return None

    def _query_vectors_by_domain(self, domain: str) -> list[dict]:
        """Read features_json from decision_vectors, extract dimension/confidence/created_at."""
        if not self.db_path.exists():
            return []
        import json
        try:
            with self._connect() as conn:
                rows = conn.execute(
                    "SELECT features_json, created_at FROM decision_vectors WHERE industry=?",
                    (domain,),
                ).fetchall()
            result = []
            for fj, created_at in rows:
                try:
                    d = json.loads(fj)
                    result.append({
                        "dimension": d.get("dimension"),
                        "confidence": d.get("confidence"),
                        "created_at": created_at,
                    })
                except (json.JSONDecodeError, TypeError):
                    pass
            return result
        except sqlite3.OperationalError:
            return []

    def _query_hunger_log(self, n: int) -> list[dict]:
        if not self.db_path.exists():
            return []
        try:
            with self._connect() as conn:
                conn.row_factory = sqlite3.Row
                rows = conn.execute(
                    "SELECT * FROM hunger_log ORDER BY id DESC LIMIT ?", (n,)
                ).fetchall()
                return [dict(r) for r in rows]
        except sqlite3.OperationalError:
            return []

    def _query_queue(self, limit: int) -> list[dict]:
        if not self.db_path.exists():
            return []
        try:
            with self._connect() as conn:
                conn.row_factory = sqlite3.Row
                rows = conn.execute(
                    "SELECT * FROM hunger_queue WHERE status='PENDING' "
                    "ORDER BY priority DESC LIMIT ?",
                    (limit,),
                ).fetchall()
                return [dict(r) for r in rows]
        except sqlite3.OperationalError:
            return []
